import {escapeHtml as esc} from "../account.js";
import {visibleEventTypes, IMPORTANCE_LEVELS} from "../event-types.js";
import {icon} from "./icons.js";

export function eventTypeList(types) {
  const visible = visibleEventTypes(types);
  return visible.length ? visible.map(type => `<li class="event-type-row"><span class="type-importance-swatch importance-${type.importance}" aria-hidden="true"></span><div><strong>${esc(type.name)}</strong><span>${IMPORTANCE_LEVELS[type.importance - 1].label}</span></div><button type="button" class="icon-button" data-action="delete-event-type" data-type-id="${esc(type.id)}" aria-label="Supprimer le type ${esc(type.name)}">${icon("trash")}</button></li>`).join("") : '<li class="event-types-empty">Crée ton premier type pour organiser tes événements.</li>';
}
export function eventTypesDialog(types) {
  return `<dialog class="app-dialog event-dialog event-types-dialog" aria-labelledby="event-types-title" aria-describedby="event-types-description"><header class="dialog-heading"><h2 id="event-types-title">Types d’événement</h2><button type="button" class="icon-button" data-action="close-event-types" aria-label="Fermer la fenêtre">${icon("close")}</button></header><p class="dialog-description" id="event-types-description">L’importance détermine la place du type dans le calendrier. La création assistée choisit le type le plus approprié au nom de l’événement.</p><ul id="event-types-list" class="event-types-list">${eventTypeList(types)}</ul><form id="event-type-form"><div class="event-fields"><div class="event-field"><label class="field-label" for="event-type-name">Nom</label><input type="text" id="event-type-name" name="name" placeholder="Ex. : Examen, cours, rendez-vous" maxlength="80" required/></div><div class="event-field"><label class="field-label" for="event-type-importance">Importance</label><select id="event-type-importance" name="importance" required><option value="" selected disabled>Choisir un niveau</option>${IMPORTANCE_LEVELS.map(level => `<option value="${level.value}">${level.label} · ${level.detail}</option>`).join("")}</select></div></div><div class="dialog-actions"><button type="submit" class="primary-button">${icon("plus")}Créer le type</button></div></form><p id="event-types-error" class="event-error" role="alert" tabindex="-1" hidden></p><p id="event-types-status" class="recurrence-summary" role="status" aria-live="polite"></p><section id="event-type-delete-confirm" class="event-confirm" hidden><strong>Supprimer ce type?</strong><p id="event-type-delete-description"></p><div><button type="button" class="secondary-button" data-action="cancel-delete-event-type">Garder le type</button><button type="button" class="danger-button" data-action="confirm-delete-event-type">Supprimer le type</button></div></section></dialog>`;
}
